$ErrorActionPreference='Stop'
. "$PSScriptRoot/iam-model-local-meter-watchdog-fix-wait.ps1"
$base="$script:WatchdogRoot/.local/iam-model-local-meter-watchdog-fix"
$records=[Collections.Generic.List[object]]::new();$guard=[OwnedDeadline]::new(3)
$failure=$null;$cleanup=$null
try{
 try{
  $p=Start-Process (Join-Path $PSHOME 'pwsh.exe') -ArgumentList @('-NoProfile','-File',('"'+$PSScriptRoot+'/iam-model-local-meter-watchdog-fix-hung.ps1"')) -WorkingDirectory $script:WatchdogRoot -WindowStyle Hidden -RedirectStandardOutput "$base/cleanup-control.stdout.log" -RedirectStandardError "$base/cleanup-control.stderr.log" -PassThru
  $r=Register-OwnProcess $p 'cleanup-failure-control';$records.Add($r);$guard.Add($p,$r.startTicks)
  Find-OwnDescendants $records $guard
  throw 'SIMULATED_CLOSE_HELPER_FAILURE'
 }finally{$cleanup=Stop-OwnProcesses $records}
}catch{$failure=$_.Exception.Message}finally{$guard.Dispose()}
$alive=@($records|Where-Object {Test-OwnAlive $_})
$result=@{simulatedFailure=$failure;cleanup=$cleanup;alive=$alive;timerFired=$guard.Fired;timerDisposedAndCallbacksCompleted=$true;actualBusinessCommandsReplayed=$false;passed=($failure -eq 'SIMULATED_CLOSE_HELPER_FAILURE' -and $alive.Count -eq 0 -and !$guard.Fired)}
Write-OwnJson "$base/finally-control.json" $result
$result|ConvertTo-Json -Depth 10
if(!$result.passed){exit 1}

using System;
using System.Collections.Concurrent;
using System.Diagnostics;
using System.Threading;
public sealed class OwnedDeadline : IDisposable {
 readonly ConcurrentDictionary<int,(Process process,long ticks)> owned = new();
 readonly ConcurrentQueue<string> errors = new();
 readonly Stopwatch watch = Stopwatch.StartNew();
 readonly Timer timer;
 int fired;
 public bool Fired => Volatile.Read(ref fired) != 0;
 public long DecisionMs {get; private set;}
 public string[] Errors => errors.ToArray();
 public OwnedDeadline(double seconds) {
  if(seconds<=0 || seconds>30) throw new ArgumentOutOfRangeException(nameof(seconds));
  timer=new Timer(_=>Expire(),null,TimeSpan.FromSeconds(seconds),Timeout.InfiniteTimeSpan);
 }
 public void Add(Process p,long ticks) {
  owned.TryAdd(p.Id,(p,ticks));
  if(Fired) Kill(p,ticks);
 }
 void Kill(Process p,long ticks) {
  try { if(!p.HasExited && p.StartTime.ToUniversalTime().Ticks==ticks) p.Kill(); }
  catch(Exception e) { errors.Enqueue(p.Id+":"+e.GetType().Name); }
 }
 void Expire() {
  DecisionMs=watch.ElapsedMilliseconds;
  Interlocked.Exchange(ref fired,1);
  foreach(var item in owned.Values) Kill(item.process,item.ticks);
 }
 public void Dispose() {
  using var done=new ManualResetEvent(false);
  if(timer.Dispose(done) && !done.WaitOne(TimeSpan.FromSeconds(10))) throw new TimeoutException("OWN_TIMER_STOP_10S");
 }
}

