class IamModelLocalMeterWatchdogFixResources {
 public static void main(String[] args)throws Exception{
  Path base=Path.of(System.getProperty("watchdog.base")),dir=Path.of(System.getProperty("binding.fixture"));
  var admin=new JdbcTemplate(new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:25432/agent_platform_v12?connectTimeout=2&socketTimeout=3","agent_v12",System.getenv("AGENT_DB_PASSWORD")));
  if(args[0].equals("close")){
   var n=Json.read(Files.readString(dir.resolve("setup.json")));String database=n.path("database").asText(),model=n.path("modelRole").asText(),engine=n.path("engineRole").asText();
   if(!database.matches("iam_model_input_meter_wd_[0-9a-f]{32}")||!model.matches("imiw_m_[0-9a-f]{32}")||!engine.matches("imiw_e_[0-9a-f]{32}"))throw new AssertionError("OWNERSHIP_REQUIRED");
   for(String role:List.of(model,engine))admin.execute("alter role "+role+" nologin nosuperuser nocreatedb nocreaterole noreplication nobypassrls");
   var result=new LinkedHashMap<String,Object>();result.put("database",database);result.put("sessions",admin.queryForObject("select count(*) from pg_stat_activity where datname=?",Integer.class,database));
   result.put("roles",admin.queryForList("select rolname,rolcanlogin,rolsuper,rolcreatedb,rolcreaterole,rolreplication,rolbypassrls from pg_roles where rolname in (?,?)",model,engine));
   var db=new JdbcTemplate(new DriverManagerDataSource("jdbc:postgresql://127.0.0.1:25432/"+database+"?connectTimeout=2&socketTimeout=3","agent_v12",System.getenv("AGENT_DB_PASSWORD")));
   result.put("schemaPrivileges",db.queryForList("select rolname,has_schema_privilege(rolname,'model','USAGE') as model_usage,has_schema_privilege(rolname,'engine','USAGE') as engine_usage from pg_roles where rolname in (?,?)",model,engine));
   result.put("businessCounters",db.queryForMap("select (select count(*) from model.call_log) as call_logs,(select count(*) from model.quota_reservation) as quotas"));
   result.put("memberships",admin.queryForObject("select count(*) from pg_auth_members m join pg_roles r on r.oid=m.member where r.rolname in (?,?)",Integer.class,model,engine));
   Files.writeString(dir.resolve("db-closure.json"),Json.write(result));return;
  }
  Path registry=base.resolve("databases.jsonl");long registered=Files.exists(registry)?Files.readAllLines(registry).size():0;if(registered>=3)throw new AssertionError("WATCHDOG_MAX3");
  String suffix=UUID.randomUUID().toString().replace("-",""),database="iam_model_input_meter_wd_"+suffix,model="imiw_m_"+suffix,engine="imiw_e_"+suffix;
  if(admin.queryForObject("select count(*) from pg_database where datname=?",Integer.class,database)!=0||admin.queryForObject("select count(*) from pg_roles where rolname in (?,?)",Integer.class,model,engine)!=0)throw new AssertionError("ABSENT_PREFLIGHT_REQUIRED");
  for(String line:Files.exists(registry)?Files.readAllLines(registry):List.<String>of()){String prior=Json.read(line).path("database").asText();if(!prior.matches("iam_model_input_meter_wd_[0-9a-f]{32}"))throw new AssertionError("REGISTRY_OWNER_REQUIRED");if(admin.queryForObject("select count(*) from pg_stat_activity where datname=?",Integer.class,prior)>0)throw new AssertionError("PREVIOUS_OWN_EPOCH_STILL_LIVE");}
  Files.writeString(registry,Json.write(Map.of("owner","iam-model-local-meter-watchdog-fix","database",database,"modelRole",model,"engineRole",engine,"absentBeforeCreate",true,"pid",ProcessHandle.current().pid()))+"\n",StandardOpenOption.CREATE,StandardOpenOption.APPEND);
  String mp=UUID.randomUUID().toString(),ep=UUID.randomUUID().toString();
  admin.execute("create role "+model+" login password '"+mp+"'");admin.execute("create role "+engine+" login password '"+ep+"'");admin.execute("create database "+database);
  String url="jdbc:postgresql://127.0.0.1:25432/"+database+"?connectTimeout=2&socketTimeout=3";
  var db=new JdbcTemplate(new DriverManagerDataSource(url,"agent_v12",System.getenv("AGENT_DB_PASSWORD")));
  db.execute("revoke connect on database "+database+" from public");db.execute("grant connect,create on database "+database+" to "+model+","+engine);
  db.execute("create schema model authorization "+model);db.execute("create schema engine authorization "+engine);db.execute("revoke all on schema public from public");db.execute("revoke all on schema model from public");db.execute("revoke all on schema engine from public");
  Files.writeString(dir.resolve("model-db.json"),Json.write(Map.of("url",url,"username",model,"password",mp,"database",database)));Files.writeString(dir.resolve("engine-db.json"),Json.write(Map.of("url",url,"username",engine,"password",ep,"database",database)));
  try(var pool=FrozenModelBindingConsumerFixture.pool(dir.resolve("model-db.json"))){Flyway.configure().dataSource(pool).schemas("model").defaultSchema("model").locations("classpath:db/migration").load().migrate();}
  Files.writeString(dir.resolve("setup.json"),Json.write(Map.of("database",database,"modelRole",model,"engineRole",engine,"closed",true,"pid",ProcessHandle.current().pid())));
 }
}

