﻿$ErrorActionPreference='Stop'
. "$PSScriptRoot/iam-model-local-meter-watchdog-fix-wait.ps1"
$root=$script:WatchdogRoot
$base="$root/.local/iam-model-local-meter-watchdog-fix"
$epoch="$base/qualification"
if(Test-Path $epoch){throw 'FRESH_EPOCH_REQUIRED'}
New-Item -ItemType Directory $epoch,"$epoch/setup","$epoch/model","$epoch/engine"|Out-Null
if(!(Get-Acl $base).AreAccessRulesProtected -or !(Get-Acl $epoch).AreAccessRulesProtected -and !(Get-Acl $epoch).Access){throw 'PRIVATE_ACL_REQUIRED'}
# Epoch inherits the protected owner-only parent; explicitly protect it before any credentials.
$acl=icacls $epoch /inheritance:r /grant:r 'Administrator:(OI)(CI)F' 'SYSTEM:(OI)(CI)F'
$ac=$LASTEXITCODE;Write-OwnJson "$epoch/acl.json" @{exit=$ac;output=@($acl);protected=(Get-Acl $epoch).AreAccessRulesProtected;sddl=(Get-Acl $epoch).Sddl;at=[DateTime]::UtcNow.ToString('O')}
if($ac -ne 0 -or !(Get-Acl $epoch).AreAccessRulesProtected){throw 'PRIVATE_ACL_REQUIRED_BEFORE_PRIVATE_WRITES'}
if(!(Test-Path 'V:/pom.xml') -or (Get-FileHash 'V:/pom.xml').Hash -ne (Get-FileHash "$root/pom.xml").Hash){throw 'V_MAPPING_REQUIRED'}
$java='C:/Program Files/Eclipse Adoptium/jdk-21.0.12.8-hotspot/bin/java.exe'
$env:JAVA_HOME=Split-Path (Split-Path $java);$env:Path="$env:JAVA_HOME/bin;$env:Path"
$cpModel=(Get-Content -Raw "$root/.local/iam-model-egress-local-meter/model-classpath.txt").Replace('\','/').Trim()
$cpEngine=(Get-Content -Raw "$root/.local/iam-model-egress-local-meter/engine-classpath.txt").Replace('\','/').Trim()
$tls="$root/.local/iam-model-input-producer/tls/engine.p12";$trust="$root/.local/iam-model-input-producer/tls/trust.p12"
$sourceSha=(Get-FileHash "$base/before/source.json").Hash.ToLower()
$helperCp="$base/helper-classes;$cpModel"
$fixtures=[Collections.Generic.List[object]]::new()
function ArgsFile($Name,$Items){
 $path="$root/.tools/iam-model-local-meter-watchdog-fix-$Name.args"
 $quoted=$Items|ForEach-Object {'"'+($_.Replace('\','/').Replace($root,'V:').Replace('"','\"'))+'"'}
 [IO.File]::WriteAllLines($path,$quoted,[Text.UTF8Encoding]::new($false));return $path
}
function Ready($Record,$Path){
 $s=[Diagnostics.Stopwatch]::StartNew()
 while(!(Test-Path $Path)){
  if(!(Test-OwnAlive $Record)){throw 'OWN_FIXTURE_EXITED'}
  if($s.Elapsed.TotalSeconds -ge 30){throw 'OWN_READINESS_30S'}
  Start-Sleep -Milliseconds 50
 }
}
function CheckExit($Result){if($Result.timedOut -or $Result.exit -ne 0){throw "OWN_CHILD_FAILED_$($Result.rootPid)_TIMEOUT_$($Result.timedOut)_EXIT_$($Result.exit)"}}
try{
 New-Item -ItemType Directory "$base/helper-classes"|Out-Null
 $compile=ArgsFile 'compile' @('-encoding','UTF-8','-cp',$cpModel,'-d',"$base/helper-classes","$root/.tools/iam-model-local-meter-watchdog-fix-resources.java")
 CheckExit (Invoke-OwnBoundedProcess ($env:JAVA_HOME+'/bin/javac.exe') @("@$compile") 'own-helper-compile' "$epoch/compile" 30)
 $env:AGENT_DB_PASSWORD=(((Get-Content "$root/.env"|Where-Object {$_ -match '^AGENT_DB_PASSWORD='}) -split '=',2)[1]).Trim('"',"'")
 $setupArgs=ArgsFile 'setup' @('-Djdk.net.unixdomain.tmpdir=V:/.local/tmp',"-Dbinding.fixture=$epoch/setup","-Dwatchdog.base=$base",'-cp',$helperCp,'IamModelLocalMeterWatchdogFixResources','setup')
 CheckExit (Invoke-OwnBoundedProcess $java @("@$setupArgs") 'own-db-setup' "$epoch/setup-run" 30)
 Remove-Item Env:AGENT_DB_PASSWORD
 Copy-Item "$epoch/setup/model-db.json" "$epoch/model/model-db.json";Copy-Item "$epoch/setup/engine-db.json" "$epoch/engine/engine-db.json"
 foreach($item in Get-ChildItem Env:|Where-Object {$_.Name -match '^AGENT_(DB|SECRET|IAM|ENGINE|MODEL)'}){Remove-Item -LiteralPath "Env:$($item.Name)"}
 Write-OwnJson "$epoch/child-env-names.json" @{removedUnrelatedServiceSecrets=$true;remainingAgentNames=@((Get-ChildItem Env:|Where-Object {$_.Name -like 'AGENT_*'}).Name)}
 $seedArgs=ArgsFile 'seed' @('-Djdk.net.unixdomain.tmpdir=V:/.local/tmp',"-Dbinding.fixture=$epoch/model","-Dconsumer.tls=$tls","-Djavax.net.ssl.trustStore=$trust",'-Djavax.net.ssl.trustStorePassword=fixture-only','-cp',$cpModel,'cn.agentplatform.model.application.FrozenInitialInputMeterFixture','serve')
 $p=Start-Process $java -ArgumentList "@$seedArgs" -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput "$epoch/seed.stdout.log" -RedirectStandardError "$epoch/seed.stderr.log" -PassThru
 $seed=Register-OwnProcess $p 'model-fixture';$fixtures.Add($seed);Write-OwnJson "$epoch/fixture-commands.json" @(@{role='model';pid=$p.Id;startTicks=$seed.startTicks;executable=$java;argfile=$seedArgs;cwd=$root})
 Ready $seed "$epoch/model/model-seed-ready.json"
 Copy-Item "$epoch/model/binding.json" "$epoch/engine/binding.json"
 $engineArgs=ArgsFile 'engine' @('-Djdk.net.unixdomain.tmpdir=V:/.local/tmp',"-Dconsumer.fixture=$epoch/engine","-Dconsumer.tls=$tls","-Dconsumer.source.sha=$sourceSha","-Djavax.net.ssl.trustStore=$trust",'-Djavax.net.ssl.trustStorePassword=fixture-only','-cp',$cpEngine,'cn.agentplatform.engine.infra.FrozenModelBindingProducerFixture')
 $p=Start-Process $java -ArgumentList "@$engineArgs" -WorkingDirectory $root -WindowStyle Hidden -RedirectStandardOutput "$epoch/engine.stdout.log" -RedirectStandardError "$epoch/engine.stderr.log" -PassThru
 $engine=Register-OwnProcess $p 'engine-fixture';$fixtures.Add($engine)
 Write-OwnJson "$epoch/fixture-commands.json" @(@{role='model';pid=$seed.pid;startTicks=$seed.startTicks;executable=$java;argfile=$seedArgs;cwd=$root},@{role='engine';pid=$engine.pid;startTicks=$engine.startTicks;executable=$java;argfile=$engineArgs;cwd=$root})
 Ready $engine "$epoch/engine/ready.json"
 foreach($file in @('ready.json','request.json','manifest.json','model-config.json','model-secret.txt','first-ticket.txt','repeat-ticket.txt','newGrant-ticket.txt','wrongOwner-ticket.txt','wrongRoot-ticket.txt','differentOrigin-ticket.txt')){Copy-Item "$epoch/engine/$file" "$epoch/model/$file"}
 $env:AGENT_SECRET_IAM_MODEL_CLIENT=Get-Content -Raw "$epoch/model/model-secret.txt"
 $mavenHome=Split-Path (Split-Path (Get-Command mvn.cmd).Source)
 $boot=(Get-ChildItem -LiteralPath "$mavenHome/boot" -Filter 'plexus-classworlds-*.jar').FullName.Replace('\','/')
 foreach($group in (Get-Content -Raw "$base/selected-cases.json"|ConvertFrom-Json).groups){
  $dir="$epoch/group-$($group.id)";New-Item -ItemType Directory $dir|Out-Null
  $arguments=@('-classpath',$boot,"-Dclassworlds.conf=$mavenHome/bin/m2.conf","-Dmaven.home=$mavenHome","-Dmaven.multiModuleProjectDirectory=$root",'org.codehaus.plexus.classworlds.launcher.Launcher','-o','-B','-ntp','-pl','admin-common,model-gateway,engine-runtime','-am','test','-Dmaven.repo.local=.tools/m2',"-Dtest=$($group.selector)",'-Dsurefire.failIfNoSpecifiedTests=false',"-Dbinding.fixture=$epoch/model","-Dconsumer.fixture=$epoch/model","-Dconsumer.tls=$tls","-Djavax.net.ssl.trustStore=$trust",'-Djavax.net.ssl.trustStorePassword=fixture-only','-Djdk.net.unixdomain.tmpdir=V:/.local/tmp')
  $argsFile=ArgsFile "group-$($group.id)" $arguments
  Write-OwnJson "$dir/selection.json" @{selector=$group.selector;cases=$group.cases;sourceSha256=$sourceSha;capSeconds=30;sequential=$true;envNames=@('JAVA_HOME','AGENT_SECRET_IAM_MODEL_CLIENT');argfile=$argsFile}
  $result=Invoke-OwnBoundedProcess $java @("@$argsFile") 'maven-launcher' "$dir/run" 30
  CheckExit $result
  & python "$root/.tools/iam-model-local-meter-watchdog-fix-capture.py" group $group.id
  if($LASTEXITCODE -ne 0){throw 'ACTUAL_GROUP_XML_FAILED'}
  Write-Output "GROUP_$($group.id)_EXIT_0_ELAPSED_MS_$($result.elapsedMs)"
 }
 & python "$root/.tools/iam-model-local-meter-watchdog-fix-capture.py" final
 if($LASTEXITCODE -ne 0){throw 'FINAL_FINITE_CAPTURE_FAILED'}
}finally{
 try{
 foreach($n in @('AGENT_DB_PASSWORD','AGENT_SECRET_IAM_MODEL_CLIENT')){if(Test-Path "Env:$n"){Remove-Item "Env:$n"}}
 if($engine){[IO.File]::WriteAllText("$epoch/engine/stop",'stop')}
 if($seed){[IO.File]::WriteAllText("$epoch/model/model-stop",'stop')}
 $stop=[Diagnostics.Stopwatch]::StartNew()
 foreach($f in $fixtures){if(Test-OwnAlive $f){$f.process.WaitForExit([Math]::Max(0,10000-[int]$stop.ElapsedMilliseconds))|Out-Null}}
